import { getLocale } from "next-intl/server";
/**
 * Authenticated app shell — the layout for every route under `(app)`.
 *
 * Checks, in order:
 *
 * 1. Session required. `getAuthSession()` is a belt-and-suspenders check
 *    (defense in depth alongside middleware, which only reads the
 *    session cookie and redirects — see the "optimistic middleware,
 *    authoritative server" convention). No session → `/login`.
 *
 * 2. Onboarding required. Reads `users.onboardingCompleted` directly via
 *    `@intelligo-dev/core/db` — no dedicated `@intelligo-dev/auth` helper exists
 *    for this yet, and a single-row, two-column lookup is cheap enough
 *    to keep inline here rather than invent a package API for one call
 *    site. Incomplete → `/onboarding`.
 *
 *    The first product's version of this layout read an `x-pathname`
 *    header (set by custom middleware) to skip this check while
 *    already on the onboarding route, to avoid a redirect loop. That
 *    dependency is dropped here on purpose: the `onboarding` registry
 *    item installs at `app/onboarding/*`, a sibling of `(app)`, not a
 *    route inside it — so this layout never wraps the onboarding flow
 *    and can never redirect into itself. If your product nests
 *    onboarding under `(app)` instead, reintroduce a route check (a
 *    pathname header, or simpler, a route-group check) before this
 *    redirect fires.
 *
 * 3. Active workspace required. `ensureUserWorkspace` (`@intelligo-dev/auth`)
 *    creates one if none exists. First-workspace provisioning (trial
 *    credits, referral bonuses, anything else your product wants to do
 *    exactly once) is bound through `@/lib/workspace-bootstrap` — never
 *    imported directly here (ADR-0005: explicit composition-root
 *    wiring, not an import side effect; it also keeps this file, and
 *    `@intelligo-dev/auth`, free of a hard dependency on billing).
 */

import { eq } from "drizzle-orm";
import { headers } from "next/headers";
import type { ReactNode } from "react";

import {
  auth,
  ensureUserWorkspace,
  getAuthSession,
  getWorkspaceContextById,
} from "@intelligo-dev/auth";
import { db } from "@intelligo-dev/core/db";
import { users } from "@intelligo-dev/core/db/schema";

import { AppSidebar } from "@/components/shell/app-sidebar";
import { ShellHeader } from "@/components/shell/shell-header";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { redirect } from "@/i18n/navigation";
import { shellConfig } from "@/lib/shell-config";
import { onWorkspaceCreated } from "@/lib/workspace-bootstrap";

export default async function AppLayout({ children }: { children: ReactNode }) {
  const session = await getAuthSession();
  if (!session) {
    redirect({ href: "/login", locale: await getLocale() });
    return null;
  }

  const [userRecord] = await db
    .select({ onboardingCompleted: users.onboardingCompleted })
    .from(users)
    .where(eq(users.id, session.user.id))
    .limit(1);

  if (userRecord && !userRecord.onboardingCompleted) {
    redirect({ href: "/onboarding", locale: await getLocale() });
    return null;
  }

  const hdrs = await headers();
  const activeWorkspaceId = await ensureUserWorkspace(session.user, hdrs, {
    onWorkspaceCreated,
  });

  const [workspaces, workspaceContext] = await Promise.all([
    auth.api.listOrganizations({ headers: hdrs }).then((orgs) => orgs ?? []),
    getWorkspaceContextById(activeWorkspaceId),
  ]);

  if (!workspaceContext) {
    redirect({ href: "/login", locale: await getLocale() });
    return null;
  }

  const workspaceList = workspaces.map((org) => ({
    id: org.id,
    name: org.name,
    slug: org.slug,
    logo: org.logo ?? null,
  }));

  return (
    <SidebarProvider>
      <AppSidebar
        workspace={workspaceContext.workspace}
        workspaces={workspaceList}
        user={{
          name: session.user.name,
          email: session.user.email,
          image: session.user.image,
        }}
      />
      <SidebarInset>
        <ShellHeader>
          {shellConfig.headerRight && (
            <div className="ml-auto flex items-center gap-2">
              <shellConfig.headerRight />
            </div>
          )}
        </ShellHeader>
        {shellConfig.bannerTop && <shellConfig.bannerTop />}
        <main className="flex-1 overflow-hidden">{children}</main>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";

/**
 * App sidebar — nav as configuration. Pass `items` to override the
 * default nav entirely; the default only covers the routes the other
 * "registry" items in this catalogue install, so most consumers will
 * want to replace it once they add their own pages.
 *
 * Nav item titles are message keys, not literal strings (ADR-0010):
 * `NavItem.titleKey` points into this item's `app-shell` namespace (e.g.
 * `"sidebar.nav.dashboard"` resolves `messages/en/app-shell.json`'s
 * `sidebar.nav.dashboard`), and this component resolves it via
 * `t(item.titleKey)`. A consumer overriding `items` supplies its own
 * keys backed by its own messages — never hardcoded titles here.
 */

import * as React from "react";
import { useTranslations } from "next-intl";
import type { LucideIcon } from "lucide-react";

import { Link, usePathname } from "@/i18n/navigation";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";
import { UserMenu } from "./user-menu";
import { WorkspaceSwitcher, type Workspace } from "./workspace-switcher";
import { navItems as configuredNavItems } from "@/lib/nav-config";

export interface NavItem {
  /**
   * Key into the `app-shell` namespace's `sidebar.nav` messages (e.g.
   * `"sidebar.nav.dashboard"`), resolved inside this component via
   * `t(item.titleKey)`. Nav config carries keys, not literal strings, so
   * a consumer overriding `items` still gets translated titles by
   * pointing at its own message keys instead of hardcoding copy here.
   */
  titleKey: string;
  href: string;
  icon?: LucideIcon;
}

interface AppSidebarProps {
  workspace: Workspace | null;
  workspaces: Workspace[];
  user: {
    name: string | null;
    email: string;
    image?: string | null;
  };
  items?: NavItem[];
}

export function AppSidebar({
  workspace,
  workspaces,
  user,
  items = configuredNavItems,
}: AppSidebarProps) {
  const pathname = usePathname();
  const t = useTranslations("app-shell");

  return (
    <Sidebar collapsible="icon">
      <SidebarHeader>
        <WorkspaceSwitcher
          currentWorkspace={workspace}
          workspaces={workspaces}
        />
      </SidebarHeader>

      <SidebarContent>
        <SidebarGroup>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => {
                const isActive =
                  pathname === item.href ||
                  pathname?.startsWith(`${item.href}/`);
                return (
                  <SidebarMenuItem key={item.href}>
                    <SidebarMenuButton
                      isActive={isActive}
                      tooltip={t(item.titleKey)}
                      render={<Link href={item.href} />}
                    >
                      {item.icon && <item.icon />}
                      <span>{t(item.titleKey)}</span>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter>
        <SidebarMenu>
          <SidebarMenuItem>
            <UserMenu user={user} />
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarFooter>
    </Sidebar>
  );
}

"use client";

/**
 * Workspace switcher — lists the caller's workspaces (server-fetched by
 * the layout, passed down as props) and activates one via Better-Auth's
 * organization plugin.
 *
 * No create-workspace dialog: creating a workspace needs a name/slug
 * form, a pending state, and error handling of its own — enough surface
 * that it deserves its own component once a product wants self-serve
 * multi-workspace creation, not something to bundle in sight-unseen.
 * Wire one up against `authClient.organization.create` when you need it.
 */

import * as React from "react";
import { useTranslations } from "next-intl";
import { Check, ChevronsUpDown } from "lucide-react";

import { authClient } from "@intelligo-dev/auth/client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { SidebarMenuButton, useSidebar } from "@/components/ui/sidebar";
import { useRouter } from "@/i18n/navigation";

export interface Workspace {
  id: string;
  name: string;
  slug: string;
  logo?: string | null;
}

interface WorkspaceSwitcherProps {
  currentWorkspace: Workspace | null;
  workspaces: Workspace[];
}

export function WorkspaceSwitcher({
  currentWorkspace,
  workspaces,
}: WorkspaceSwitcherProps) {
  const { isMobile } = useSidebar();
  const router = useRouter();
  const [isSwitching, setIsSwitching] = React.useState(false);
  const t = useTranslations("app-shell");

  if (!currentWorkspace) return null;

  async function handleSwitch(workspaceId: string) {
    if (!currentWorkspace || workspaceId === currentWorkspace.id) return;
    setIsSwitching(true);
    try {
      await authClient.organization.setActive({ organizationId: workspaceId });
      router.refresh();
    } catch (error) {
      console.error("Failed to switch workspace:", error);
    } finally {
      setIsSwitching(false);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <SidebarMenuButton
            size="lg"
            disabled={isSwitching}
            className="data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground"
          />
        }
      >
        <div className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-sidebar-primary text-xs font-semibold text-sidebar-primary-foreground">
          {currentWorkspace.name[0]?.toUpperCase()}
        </div>
        <div className="grid flex-1 text-left leading-tight">
          <span className="truncate text-sm font-medium">
            {currentWorkspace.name}
          </span>
          <span className="truncate text-xs text-muted-foreground">
            {currentWorkspace.slug}
          </span>
        </div>
        {workspaces.length > 1 && (
          <ChevronsUpDown className="ml-auto size-4 opacity-50" />
        )}
      </DropdownMenuTrigger>
      {workspaces.length > 1 && (
        <DropdownMenuContent
          className="w-(--anchor-width) min-w-56"
          align="start"
          side={isMobile ? "bottom" : "right"}
          sideOffset={4}
        >
          <DropdownMenuGroup>
            <DropdownMenuLabel className="text-xs text-muted-foreground">
              {t("workspaceSwitcher.workspacesLabel")}
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            {workspaces.map((ws) => (
              <DropdownMenuItem
                key={ws.id}
                onClick={() => handleSwitch(ws.id)}
                disabled={isSwitching}
                className="gap-2"
              >
                <div className="flex size-6 shrink-0 items-center justify-center rounded-md bg-sidebar-primary text-xs font-semibold text-sidebar-primary-foreground">
                  {ws.name[0]?.toUpperCase()}
                </div>
                <div className="grid flex-1 leading-tight">
                  <span className="truncate text-sm">{ws.name}</span>
                  <span className="truncate text-xs text-muted-foreground">
                    {ws.slug}
                  </span>
                </div>
                {ws.id === currentWorkspace.id && (
                  <Check className="ml-auto size-4" />
                )}
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        </DropdownMenuContent>
      )}
    </DropdownMenu>
  );
}

"use client";

/**
 * User menu — avatar dropdown with profile/settings links, an optional
 * theme toggle, and sign out.
 *
 * The theme submenu is guarded, not required: `next-themes`'s
 * `useTheme()` degrades to a no-op setter when no `ThemeProvider` is
 * mounted, so this menu renders fine either way — wrap the root layout
 * in a `ThemeProvider` to make it actually switch themes. The `mounted`
 * check avoids a hydration mismatch between the server render (no theme
 * yet) and the client's resolved theme.
 *
 * No notifications entry: that surface belongs to the separate
 * `notifications` registry item. Once it's installed, add:
 *   <DropdownMenuItem render={<Link href="/notifications" />}>
 *     <Bell />Notifications
 *   </DropdownMenuItem>
 */

import * as React from "react";
import { useTranslations } from "next-intl";
import {
  ChevronsUpDown,
  LogOut,
  Monitor,
  Moon,
  Settings,
  Sun,
  User,
} from "lucide-react";
import { useTheme } from "next-themes";

import { authClient } from "@intelligo-dev/auth/client";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Link, useRouter } from "@/i18n/navigation";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { SidebarMenuButton, useSidebar } from "@/components/ui/sidebar";

interface UserMenuProps {
  user: {
    name: string | null;
    email: string;
    image?: string | null;
  };
}

export function UserMenu({ user }: UserMenuProps) {
  const { isMobile } = useSidebar();
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = React.useState(false);
  const router = useRouter();
  const t = useTranslations("app-shell");

  React.useEffect(() => {
    setMounted(true);
  }, []);

  const initials = user.name
    ? user.name
        .split(" ")
        .map((part) => part[0])
        .join("")
        .toUpperCase()
        .slice(0, 2)
    : user.email[0]?.toUpperCase();

  async function handleSignOut() {
    await authClient.signOut();
    router.push("/login");
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <SidebarMenuButton
            size="lg"
            className="data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground"
          />
        }
      >
        <Avatar className="size-8 rounded-lg">
          {user.image && <AvatarImage src={user.image} alt={user.name ?? ""} />}
          <AvatarFallback className="rounded-lg">{initials}</AvatarFallback>
        </Avatar>
        <div className="grid flex-1 text-left leading-tight">
          <span className="truncate text-sm font-medium">
            {user.name || user.email.split("@")[0]}
          </span>
          <span className="truncate text-xs text-muted-foreground">
            {user.email}
          </span>
        </div>
        <ChevronsUpDown className="ml-auto size-4 opacity-50" />
      </DropdownMenuTrigger>
      <DropdownMenuContent
        className="w-(--anchor-width) min-w-56"
        side={isMobile ? "bottom" : "top"}
        align="end"
        sideOffset={4}
      >
        <DropdownMenuGroup>
          <DropdownMenuLabel className="p-0 font-normal">
            <div className="flex items-center gap-2 px-2 py-1.5">
              <Avatar className="size-8 rounded-lg">
                {user.image && (
                  <AvatarImage src={user.image} alt={user.name ?? ""} />
                )}
                <AvatarFallback className="rounded-lg">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <div className="grid flex-1 leading-tight">
                <span className="truncate text-sm font-medium">
                  {user.name || user.email.split("@")[0]}
                </span>
                <span className="truncate text-xs text-muted-foreground">
                  {user.email}
                </span>
              </div>
            </div>
          </DropdownMenuLabel>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />

        <DropdownMenuGroup>
          <DropdownMenuItem render={<Link href="/settings" />}>
            <User />
            {t("userMenu.profile")}
          </DropdownMenuItem>
          <DropdownMenuItem render={<Link href="/settings/workspace" />}>
            <Settings />
            {t("userMenu.workspaceSettings")}
          </DropdownMenuItem>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />

        <DropdownMenuSub>
          <DropdownMenuSubTrigger>
            {mounted && theme === "dark" ? <Moon /> : <Sun />}
            {t("userMenu.theme")}
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            <DropdownMenuItem onClick={() => setTheme("light")}>
              <Sun />
              {t("userMenu.themeLight")}
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => setTheme("dark")}>
              <Moon />
              {t("userMenu.themeDark")}
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => setTheme("system")}>
              <Monitor />
              {t("userMenu.themeSystem")}
            </DropdownMenuItem>
          </DropdownMenuSubContent>
        </DropdownMenuSub>

        <DropdownMenuSeparator />
        <DropdownMenuItem
          onClick={handleSignOut}
          className="text-destructive focus:text-destructive"
        >
          <LogOut />
          {t("userMenu.signOut")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Minimal shell top bar. Its one required job is exposing
 * `SidebarTrigger`: on mobile the sidebar renders as an off-canvas
 * sheet, and without a trigger somewhere there is no way to open it.
 *
 * Pass `children` to add page-specific breadcrumbs or actions without
 * editing this file — e.g. `<ShellHeader><Breadcrumb ... /></ShellHeader>`
 * from a page that wants one. A page that doesn't need a header slot
 * can ignore this entirely and render `<ShellHeader />` as-is.
 */

import type { ReactNode } from "react";

import { Separator } from "@/components/ui/separator";
import { SidebarTrigger } from "@/components/ui/sidebar";

interface ShellHeaderProps {
  children?: ReactNode;
}

export function ShellHeader({ children }: ShellHeaderProps) {
  return (
    <header className="flex h-14 shrink-0 items-center gap-2 border-b px-4">
      <SidebarTrigger className="-ml-1" />
      <Separator orientation="vertical" className="mr-2 h-4" />
      {children}
    </header>
  );
}

import "server-only";

/**
 * Workspace bootstrap — composition-root binding for the app shell's one
 * extension point: what happens the first time `ensureUserWorkspace`
 * (`@intelligo-dev/auth`) has to create a workspace for a user, instead of
 * finding an existing one.
 *
 * `@intelligo-dev/auth` must not import `@intelligo-dev/billing` — a product's
 * trial/referral/welcome-bonus rules are a business decision, not a
 * framework one, and importing them directly would recreate the very
 * auth → billing cycle `ensureUserWorkspace`'s callback parameter exists
 * to avoid. So the layout injects this callback instead of the package
 * importing anything. Per ADR-0005, that binding happens here, in a file
 * the composition root owns and calls explicitly — never as an import
 * side effect.
 *
 * Ships provisioning nothing: a fresh install has no trial or referral
 * program to wire up. Bind whatever your product actually wants to
 * happen on first workspace creation — the commented example below
 * shows the shape once `@intelligo-dev/billing` is installed.
 */
export async function onWorkspaceCreated(_params: {
  workspaceId: string;
  email: string;
}): Promise<void> {
  // Provisions nothing by default.
}

// Example — grant trial credits on first workspace creation once
// `@intelligo-dev/billing` is installed (uncomment and adjust; remove the
// no-op export above):
//
// import { provisionTrialCredits } from "@intelligo-dev/billing";
//
// export async function onWorkspaceCreated({
//   workspaceId,
//   email,
// }: {
//   workspaceId: string;
//   email: string;
// }): Promise<void> {
//   await provisionTrialCredits({ workspaceId, email, ipAddress: undefined });
